WITH valid_inventory AS (SELECT * FROM inventory WHERE MONTH(last_restock) IN (5, 7, 9) AND store_id IN (2, 3, 5) AND last_restock <= '2025-08-17'), Summary AS (SELECT CASE WHEN quantity >= 229 THEN 'high' WHEN quantity >= 92 THEN 'mid' ELSE 'low' END AS quantity_bucket, product_id, AVG(quantity) AS avg_quantity, MAX(quantity) AS max_quantity FROM valid_inventory GROUP BY CASE WHEN quantity >= 229 THEN 'high' WHEN quantity >= 92 THEN 'mid' ELSE 'low' END, product_id) SELECT * FROM Summary WHERE avg_quantity < 180 ORDER BY quantity_bucket DESC, product_id LIMIT 10
